script:
(function gameCore(scene,api,dt){
  const key="__AURENIX_LACRES_BRUMA_V1__";
  if(!window[key]){
    const chapterNames=["Refúgio do Farol","Bosque dos Sussurros","Forja Silenciosa","Torre do Décimo Terceiro Sino"];
    const regionNames={bosque:chapterNames[1],forja:chapterNames[2],torre:chapterNames[3]};
    const lore=[
      {title:"Prólogo — A Décima Terceira Batida",body:"No mundo de Orval, toda lembrança era guardada em pequenos lacres de metal. Quando o Grande Sino tocou pela décima terceira vez, cidades esqueceram seus nomes, rios perderam os caminhos e as pessoas pararam de reconhecer os próprios rostos. Só o farol de Eira continuou brilhando. Você é o último dos Catadores de Ecos: alguém capaz de abrir os baús onde o passado ficou preso."},
      {title:"I — O Cartógrafo sem Rosto",body:"Na primeira noite da Névoa, o cartógrafo Kael entrou no bosque levando um mapa com uma estrada que não existia. Ele escreveu uma frase na margem: 'A bruma não destrói memórias. Ela as escolhe.' Depois desapareceu. Um dos seus lacres foi encontrado no interior de um baú, ainda quente."},
      {title:"II — As Máquinas que Sonhavam",body:"A Forja Silenciosa construiu relógios para medir o tempo até a próxima batida do Sino. Mas nenhuma máquina concordava com as outras. Os artesãos descobriram que o tempo não estava quebrado: cada pessoa agora vivia numa lembrança diferente. Mira foi a única a perceber que as peças retiradas dos baús tinham sempre o mesmo símbolo: um olho fechado."},
      {title:"III — A Promessa de Eira",body:"Eira não construiu o farol para guiar viajantes, mas para lembrar o nome do filho que havia perdido. Todas as noites, ela o acendia e contava treze batidas em silêncio. O décimo terceiro toque nunca deveria existir. Para impedir que o mundo esquecesse a dor, alguém roubou a última batida e a escondeu numa torre."},
      {title:"IV — O Regente do Silêncio",body:"O Regente era a voz do próprio Sino. Não era um monstro: nasceu do desejo de apagar histórias tristes. Aprendeu a proteger cada memória num baú e, em troca, fez com que ninguém conseguisse se lembrar de quem era. O Regente espera no topo da Torre. Quando o enfrentar, estará lutando contra a tentação de esquecer."},
      {title:"Epílogo — O Mundo Lembra",body:"Ao quebrar o lacre do Sino, você não devolveu apenas os nomes das cidades. Devolveu também saudade, medo e arrependimento. Eira lembrou do filho. Kael voltou a reconhecer o próprio mapa. A bruma permaneceu nas florestas — mas agora guardava histórias, não pessoas. Ainda existem lacres perdidos. Talvez um último baú esteja esperando por você."}
    ];
    const tiers=[
      {name:"Comum",color:"#bcd0dd",weight:56,coins:[9,17],dust:1},
      {name:"Incomum",color:"#6ce2ac",weight:27,coins:[16,28],dust:2},
      {name:"Raro",color:"#74b5ff",weight:12,coins:[27,44],dust:3},
      {name:"Épico",color:"#ca91ff",weight:4,coins:[43,69],dust:5},
      {name:"Lendário",color:"#ffc86c",weight:1,coins:[75,120],dust:9}
    ];
    const relicPool=[
      ["Pedaço de Barbante","Prego de Eira","Lacre Enferrujado","Moeda Sem Face"],
      ["Pena do Vigia","Fio de Luz","Chave Retorcida","Botão de Kael"],
      ["Lâmina de Orvalho","Olho de Âmbar","Mapa Invertido","Brasa da Forja"],
      ["Relógio Sem Ponteiros","Manto de Treze Estrelas","Coração da Lanterna"],
      ["A Última Batida","Nome Verdadeiro de Eira","Núcleo do Silêncio"]
    ];
    const boosts={
      blade:{name:"Lâmina Ecoante",desc:"+1 dano por nível",base:45,max:6,icon:"⚔️"},
      boots:{name:"Botas do Cartógrafo",desc:"+22 de velocidade por nível",base:35,max:6,icon:"👟"},
      light:{name:"Lanterna de Eira",desc:"+20 vida máxima por nível",base:40,max:5,icon:"🏮"},
      luck:{name:"Instinto do Catador",desc:"Mais chance de baús raros",base:65,max:5,icon:"🍀"},
      bag:{name:"Bolsa sem Fundo",desc:"+2 baús por expedição",base:60,max:4,icon:"🎒"}
    };
    const fresh=()=>({coins:0,dust:0,totalChests:0,totalKills:0,deaths:0,wins:0,seen:{},relics:[],upgrades:{blade:0,boots:0,light:0,luck:0,bag:0},chapter:0,stats:{bestRarity:0,bestRun:0},intro:false});
    const x=document;
    const q=id=>x.getElementById(id);
    const g={
      profile:null,started:false,scene:"",run:null,hp:100,attackCd:0,hurtCd:0,dir:{x:1,y:0},
      prevB:false,mobs:[],chests:[],shots:[],fx:[],queue:[],near:null,modal:"",msgEnd:0,lastHud:-1,
      danger:0,globalClock:0,warningCd:0,boss:null,pendingReport:null,pendingEnding:false,
      ui:false,assets:{closed:"lb-chest",open:"lb-open",hero:"lb-hero",moth:"lb-moth",clock:"lb-clock",ghost:"lb-ghost",boss:"lb-boss"}
    };
    const rnd=(lo,hi)=>lo+Math.random()*(hi-lo);
    const pick=a=>a[Math.floor(Math.random()*a.length)];
    const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
    const escape=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
    function save(api){api.saveData("lacres-profile-1",g.profile);}
    function initUI(){
      if(g.ui)return;g.ui=true;
      const root=x.createElement("div");root.id="lb-ui";
      root.innerHTML=`<style>
#lb-ui{position:fixed;inset:0;z-index:100;font-family:system-ui,-apple-system,sans-serif;color:#eef7fb;pointer-events:none;user-select:none}
#lb-ui *{box-sizing:border-box}#lb-ui button{cursor:pointer;touch-action:manipulation}
#lb-ui .lb-top{position:absolute;left:max(9px,env(safe-area-inset-left));top:max(9px,env(safe-area-inset-top));width:min(282px,64vw);padding:11px 13px;background:#101d31dd;border:1px solid #6dbba35c;border-radius:14px;box-shadow:0 6px 20px #0005;backdrop-filter:blur(8px)}
#lb-ui .lb-region{color:#82fbd6;font:900 12px system-ui;letter-spacing:.8px}#lb-ui .lb-small{color:#d6e5ed;font-size:11px;margin-top:5px;line-height:1.45}#lb-ui .lb-bar{background:#40293c;border-radius:99px;height:8px;overflow:hidden;margin-top:8px}#lb-ui .lb-health{height:100%;background:linear-gradient(90deg,#54ecc0,#9af5aa);transition:width .1s}
#lb-ui .lb-menu{position:absolute;top:max(9px,env(safe-area-inset-top));right:max(9px,env(safe-area-inset-right));pointer-events:auto;min-width:77px;min-height:44px;border:1px solid #d6b97790;background:#19253fe8;border-radius:12px;color:#fff;font-weight:800;padding:10px}
#lb-ui .lb-near{position:absolute;bottom:calc(163px + env(safe-area-inset-bottom,0px));left:50%;transform:translateX(-50%);padding:9px 12px;color:#fff;background:#163145e8;border-radius:12px;border:1px solid #80d9c9;max-width:80vw;text-align:center;font:800 12px system-ui;display:none}
#lb-ui .lb-interact{position:absolute;bottom:calc(88px + env(safe-area-inset-bottom,0px));left:50%;transform:translateX(-50%);pointer-events:auto;min-width:135px;min-height:46px;padding:9px;border-radius:13px;border:1px solid #8ef6cf;background:#193f46e8;color:#b7ffec;font:900 13px system-ui;display:none}
#lb-ui .lb-toast{position:absolute;top:22%;left:50%;transform:translateX(-50%);max-width:min(450px,90vw);padding:12px 16px;border-radius:14px;background:#10263fe8;border:1px solid #a9ecd5;color:white;text-align:center;font-weight:800;font-size:13px;opacity:0;transition:opacity .15s}
#lb-ui .lb-overlay{pointer-events:auto;position:absolute;inset:0;background:#060e1acc;display:flex;align-items:center;justify-content:center;padding:17px;touch-action:pan-y;overflow:auto}
#lb-ui .lb-overlay[hidden]{display:none}
#lb-ui .lb-panel{width:min(530px,100%);max-height:min(85dvh,680px);overflow-y:auto;padding:22px;background:linear-gradient(150deg,#152b3c,#19192f);border:1px solid #7bdbc29c;border-radius:22px;box-shadow:0 20px 70px #000a}
#lb-ui h2{font-weight:950;font-size:clamp(22px,5.2vw,30px);color:#91f8db;margin:0 28px 12px 0;letter-spacing:.4px}
#lb-ui h3{font-size:16px;margin:17px 0 5px;color:#ffe09e}
#lb-ui p{font-size:14px;line-height:1.58;color:#cfdfe7}
#lb-ui .lb-italic{font-style:italic;border-left:2px solid #75d8c1;padding:8px 12px;background:#ffffff08}
#lb-ui .lb-close{float:right;background:#30445b;border:0;color:white;width:42px;height:42px;border-radius:11px;font-size:22px}
#lb-ui .lb-btn{width:100%;display:block;text-align:left;margin:9px 0;padding:13px 15px;min-height:48px;border-radius:12px;background:#23455a;border:1px solid #8ce9ce66;color:#f1fbff;font-weight:800;font-size:13px}
#lb-ui .lb-btn small{display:block;opacity:.7;font-weight:500;margin-top:4px;font-size:11px}
#lb-ui .lb-btn:disabled{opacity:.43;cursor:not-allowed}
#lb-ui .lb-badges{display:flex;flex-wrap:wrap;gap:7px;margin:12px 0}
#lb-ui .lb-badge{display:inline-block;font:800 11px system-ui;padding:6px 9px;border-radius:9px;background:#2b4255;color:#dbedfc}
#lb-ui .lb-list{display:grid;gap:7px}
#lb-ui .lb-item{padding:10px;border-radius:11px;background:#ffffff09;border:1px solid #ffffff1a}
#lb-ui .lb-meta{font-size:11px;color:#99b7c6}
@media(max-width:440px){#lb-ui .lb-top{padding:8px 10px;width:61vw}#lb-ui .lb-small{font-size:10px}#lb-ui .lb-panel{padding:17px}#lb-ui .lb-interact{bottom:calc(146px + env(safe-area-inset-bottom,0px));min-height:42px}#lb-ui .lb-near{bottom:calc(200px + env(safe-area-inset-bottom,0px))}}
@media(hover:hover){#lb-ui .lb-btn:hover{background:#326078}}
</style>
<div class="lb-top" aria-live="off"><div class="lb-region" id="lb-region">LACRES DA BRUMA</div><div id="lb-info" class="lb-small">As lembranças estão esperando.</div><div class="lb-bar"><div id="lb-health" class="lb-health"></div></div></div>
<button type="button" class="lb-menu" data-act="menu">☰ MENU</button>
<div class="lb-near" id="lb-near"></div><button type="button" class="lb-interact" id="lb-interact" data-act="interact">✦ INTERAGIR</button>
<div class="lb-toast" id="lb-toast" role="status" aria-live="polite"></div>
<div class="lb-overlay" id="lb-overlay" hidden><section class="lb-panel"><button type="button" aria-label="Fechar" class="lb-close" data-act="close">×</button><div id="lb-modal"></div></section></div>`;
      x.body.appendChild(root);
      root.addEventListener("click",e=>{
        const btn=e.target.closest("button[data-act]");
        if(!btn||btn.disabled)return;
        e.preventDefault();
        g.queue.push({name:btn.dataset.act,value:btn.dataset.value||""});
      });
      const a=q("jumpBtn"),b=q("actionBtn");if(a){a.textContent="⚔";a.title="Atacar (A/Espaço)";}if(b){b.textContent="✦";b.title="Interagir (B/F)";}
    }
    function toast(message,color="#a2f5dc"){
      if(!g.ui)return;
      const node=q("lb-toast");node.textContent=message;node.style.borderColor=color;node.style.opacity="1";g.msgEnd=performance.now()+2600;
    }
    function bookUnlocked(i){
      const p=g.profile;
      if(i===0)return true;
      if(i===1)return p.totalChests>=2;
      if(i===2)return !!p.seen.forja||p.totalChests>=8;
      if(i===3)return p.totalChests>=11;
      if(i===4)return p.totalChests>=14;
      return p.wins>0;
    }
    function openPanel(kind){
      g.modal=kind;const overlay=q("lb-overlay"),m=q("lb-modal");
      if(!overlay||!m)return;
      overlay.hidden=false;
      const p=g.profile;
      const button=(act,label,sub="",value="",disabled=false)=>`<button class="lb-btn" data-act="${act}" data-value="${value}" ${disabled?"disabled":""}>${label}${sub?`<small>${sub}</small>`:""}</button>`;
      if(kind==="story")m.innerHTML=`<h2>🏮 Lacres da Bruma</h2><p class="lb-italic">${lore[0].body}</p><p>Você despertou no Refúgio do Farol. <b>Mira</b>, a última arquivista, acredita que os baús espalhados pela Névoa guardam a verdade sobre a Décima Terceira Batida.</p>${button("routes","Começar a explorar","Abra baús, reúna moedas e aprimore suas habilidades.")}${button("book","Ler o códice","Conheça a história desde o começo.")}`;
      else if(kind==="menu")m.innerHTML=`<h2>🏮 Refúgio & Jornada</h2><p>Seu progresso é salvo neste aparelho quando você retorna ao refúgio ou compra melhorias.</p><div class="lb-badges"><span class="lb-badge">🪙 ${p.coins} moedas</span><span class="lb-badge">✦ ${p.dust} ecos</span><span class="lb-badge">📦 ${p.totalChests} baús</span><span class="lb-badge">🏆 ${p.wins} vitórias</span></div>${g.run?button("return","↩ Retornar e guardar o saque","Sem punição por voltar cedo."):button("routes","🧭 Escolher expedição")}${button("inventory","🎒 Coleção de relíquias")}${button("book","📜 Códice de Orval")}${!g.run?button("shop","⚒ Oficina de Mira"):""}${button("help","❔ Como jogar")}`;
      else if(kind==="routes")m.innerHTML=`<h2>🧭 Onde explorar?</h2><p>Pequenas expedições, tesouros diferentes. Quanto mais fundo você vai, mais valiosos os baús — e mais perigosos os guardiões.</p>${button("travel","🌲 Bosque dos Sussurros","Início • baús e criaturas de névoa","bosque")}${button("travel","⚙️ Forja Silenciosa","Desbloqueie ao guardar 5 baús no total.","forja",p.totalChests<5)}${button("travel","🔔 Torre do Décimo Terceiro Sino","Desbloqueie com 12 baús e uma visita à Forja.","torre",p.totalChests<12||!p.seen.forja)}<p class="lb-meta">Você sempre pode retornar para guardar o saque. Depois do final, a torre pode ser explorada novamente.</p>`;
      else if(kind==="shop")m.innerHTML=`<h2>⚒ Oficina de Mira</h2><p>“Ninguém compra o passado. Mas dá para afiar as ferramentas que vão encontrá-lo.”</p><div class="lb-badges"><span class="lb-badge">🪙 ${p.coins} moedas</span><span class="lb-badge">✦ ${p.dust} ecos</span></div>`+Object.entries(boosts).map(([id,b])=>{
        const level=p.upgrades[id]||0,cost=b.base*(level+1),maxed=level>=b.max;
        return button("buy",`${b.icon} ${b.name} • Nv.${level}/${b.max}`,`${b.desc} · ${maxed?"MÁXIMO":cost+" moedas"}`,id,maxed||p.coins<cost);
      }).join("")+button("routes","🧭 Ir explorar");
      else if(kind==="book")m.innerHTML=`<h2>📜 Códice de Orval</h2><p class="lb-italic">“Não procure os tesouros pelo ouro. Procure pelo que eles estão tentando guardar.” — Kael</p>`+lore.map((entry,i)=>`<div class="lb-item"><b>${bookUnlocked(i)?escape(entry.title):"🔒 Capítulo "+i+" — Lacrado"}</b><p>${bookUnlocked(i)?escape(entry.body):"Continue abrindo baús e avançando na jornada para revelar esta memória."}</p></div>`).join("")+button("inventory","Ver coleção de relíquias");
      else if(kind==="inventory")m.innerHTML=`<h2>🎒 Coleção de Relíquias</h2><p>Uma lembrança de cada tipo que você conseguiu salvar. Itens repetidos viram moedas e ecos.</p><div class="lb-badges"><span class="lb-badge">${p.relics.length} / ${relicPool.flat().length+1} encontradas</span><span class="lb-badge">Lendárias: ${p.relics.filter(s=>relicPool[4].includes(s)).length}</span></div><div class="lb-list">${p.relics.length?p.relics.map(n=>`<div class="lb-item">✦ ${escape(n)}</div>`).join(""):"<div class='lb-item'>Nenhuma relíquia guardada. Abra baús raros para começar a coleção!</div>"}</div>${g.run?button("return","↩ Guardar meu saque"):button("routes","🧭 Mais uma expedição")}`;
      else if(kind==="help")m.innerHTML=`<h2>❔ Como jogar</h2><p>📱 <b>Analógico:</b> movimentar. <b>⚔ A:</b> atacar os guardiões próximos. <b>✦ B:</b> abrir baús, conversar e atravessar portais.</p><p>⌨️ No computador: <b>WASD/setas</b> para andar, <b>Espaço</b> para atacar e <b>F</b> para interagir.</p><p>Todo baú oferece moedas e ecos. Baús raros também podem conter relíquias permanentes. Volte ao refúgio para guardar tudo. Se ficar sem vida, metade das moedas e dos ecos é preservada.</p><p>O Bosque abre a Forja. A Forja abre a Torre. Encontre o Regente, descubra a história do Sino e continue em busca da coleção.</p>${button("close","Continuar jogando")}`;
      else if(kind==="report"){
        const r=g.pendingReport||{chests:0,coins:0,dust:0,relics:[],died:false};
        m.innerHTML=`<h2>${r.died?"🌫️ A bruma venceu desta vez":"🏮 Expedição concluída"}</h2><p>${r.died?"Você perdeu metade do que carregava, mas preservou as lembranças.":"O farol recebeu o seu saque. A cada retorno, uma nova chance de descobrir algo único."}</p><div class="lb-badges"><span class="lb-badge">📦 ${r.chests} baús</span><span class="lb-badge">🪙 +${r.coins} moedas</span><span class="lb-badge">✦ +${r.dust} ecos</span><span class="lb-badge">💎 ${r.relics.length} relíquias</span></div>${r.relics.length?`<p>${r.relics.map(escape).join(" • ")}</p>`:""}${button("shop","⚒ Melhorar equipamento")}${button("routes","🧭 Só mais uma expedição...")}`;
      }else if(kind==="ending")m.innerHTML=`<h2>🔔 A Última Batida</h2><p class="lb-italic">${lore[5].body}</p><p><b>Você terminou a história principal!</b> Mas ainda existem relíquias para colecionar, aprimoramentos para comprar e expedições com baús de raridade variável.</p>${button("inventory","💎 Ver minhas relíquias")}${button("routes","🧭 Continuar explorando")}`;
    }
    function closePanel(){g.modal="";const over=q("lb-overlay");if(over)over.hidden=true;}
    function maxHp(){return 90+g.profile.upgrades.light*20;}
    function newRun(region){
      g.run={region,opened:0,coins:0,dust:0,relics:[],kills:0,rares:0,misses:0,time:0};
      g.hp=maxHp();g.attackCd=0;g.hurtCd=0;g.boss=null;
      g.pendingReport=null;
    }
    function stageEnter(scene,api){
      g.scene=api.sceneName;g.mobs=[];g.chests=[];g.shots=[];g.fx=[];g.near=null;g.boss=null;g.prevB=false;
      if(g.scene===chapterNames[0]){
        g.run=null;g.hp=maxHp();
        if(g.pendingEnding){g.pendingEnding=false;openPanel("ending");}
        else if(g.pendingReport)openPanel("report");
        else if(!g.profile.intro){g.profile.intro=true;save(api);openPanel("story");}
        else{toast("Você está a salvo no Refúgio. Hora de escolher um novo caminho.");}
      }else{
        const region=Object.keys(regionNames).find(k=>regionNames[k]===g.scene)||"bosque";
        if(!g.run||g.run.region!==region)newRun(region);
        g.profile.seen[region]=true;save(api);
        spawnChests(scene,api,region);
        spawnMobs(scene,api,region);
        toast("Exploração iniciada • abra baús e não deixe a Bruma te encontrar!");
      }
    }
    const spots=[
      [-425,-257],[-255,-295],[-55,-285],[170,-278],[401,-280],
      [-390,230],[-200,270],[24,285],[265,273],[430,225],
      [-285,-45],[-80,138],[158,-98],[342,42],[-38,-95],[500,-82],
      [10,5],[-155,-167],[285,-160],[100,203]
    ];
    const enemySpots=[[-270,-180],[-50,-245],[225,-235],[355,160],[-395,145],[104,80],[-75,185],[430,-75],[225,265],[-210,80]];
    function spawnChests(scene,api,region){
      const shuffled=spots.slice().sort(()=>Math.random()-.5);
      const num=region==="bosque"?8:region==="forja"?9:8;
      for(let i=0;i<num;i++){
        const [x,y]=shuffled[i];
        const halo=api.spawn("circle",{name:"Halo de Lacre",x,y,w:55,h:55,opacity:.11,color:region==="torre"?"#ffb071":"#95f9e1",layer:4,anchored:true});
        const chest=api.spawn("sprite",{name:"Baú Selado "+(i+1),x,y,w:45,h:42,assetId:g.assets.closed,layer:12,anchored:true,tags:"bau"});
        g.chests.push({id:chest.id,halo:halo.id,open:false,x,y});
      }
    }
    function spawnMobs(scene,api,region){
      const count=region==="bosque"?5:region==="forja"?7:6;
      const chosen=enemySpots.slice().sort(()=>Math.random()-.5).slice(0,count);
      for(let i=0;i<count;i++){
        const [x,y]=chosen[i];
        const kind=region==="bosque"?(i%3===0?"ghost":"moth"):region==="forja"?(i%2?"clock":"ghost"):(i%3===0?"moth":"clock");
        const asset=g.assets[kind];
        const mob=api.spawn("sprite",{name:"Guardião de Névoa "+(i+1),x,y,w:35,h:37,assetId:asset,color:"#dd98ba",layer:16,anchored:true,tags:"inimigo"});
        g.mobs.push({id:mob.id,kind,hp:kind==="clock"?3:2,maxHp:kind==="clock"?3:2,speed:kind==="moth"?67:kind==="clock"?59:54,hitCd:0,shotCd:rnd(1.3,3),orbit:rnd(-3.14,3.14)});
      }
      if(region==="torre"){
        const boss=api.spawn("sprite",{name:"O Regente do Silêncio",x:385,y:-26,w:116,h:130,assetId:g.assets.boss,opacity:0,layer:18,anchored:true,tags:"boss"});
        g.boss={id:boss.id,hp:20,maxHp:20,awake:false,shotCd:2.5,phase:0};
      }
    }
    function zoneIndex(){return g.scene===chapterNames[1]?0:g.scene===chapterNames[2]?1:2;}
    function coinRoll(tier){const t=tiers[tier],mult=1+zoneIndex()*.34+(g.profile.wins>0?.2:0);return Math.round(rnd(t.coins[0],t.coins[1])*mult);}
    function rarityRoll(){
      const luck=g.profile.upgrades.luck||0,zone=zoneIndex();
      const weights=tiers.map(t=>t.weight);
      const shift=luck*1.9+zone*1.35+(g.profile.wins>0?1.2:0);
      weights[0]=Math.max(16,weights[0]-shift*2.2);weights[1]=Math.max(13,weights[1]-shift*.45);
      weights[2]+=shift*1.55;weights[3]+=shift*.82;weights[4]+=shift*.28;
      const total=weights.reduce((a,b)=>a+b,0);let roll=Math.random()*total;
      for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<=0)return i;}return 4;
    }
    function fxText(api,t,color,x,y){
      const o=api.spawn("text",{name:"Efeito",text:t,fontSize:14,color,x,y,w:260,h:30,layer:30});
      g.fx.push({id:o.id,life:1.2});
    }
    function chestOpen(api,chest){
      if(!g.run||chest.open)return;
      if(g.run.opened>=8+g.profile.upgrades.bag*2){toast("🎒 Bolsa cheia. Guarde suas memórias no refúgio!","#ffce9c");return;}
      const o=api.get(chest.id);if(!o)return;
      chest.open=true;o.assetId=g.assets.open;o.opacity=.75;
      const halo=api.get(chest.halo);if(halo)halo.color="#f0d18b";
      let tier=rarityRoll(); if(g.run.misses>=5&&tier<2)tier=2;g.run.misses=tier>=2?0:(g.run.misses||0)+1;const t=tiers[tier],coins=coinRoll(tier),dust=t.dust+zoneIndex();
      const bonus=(g.run.opened+1)%5===0?7:0;
      g.run.coins+=coins+bonus;g.run.dust+=dust;g.run.opened++;
      if(tier>=2){g.run.rares++;const relic=pick(relicPool[tier]);g.run.relics.push(relic);}
      else if(Math.random()<.10)g.hp=Math.min(maxHp(),g.hp+12);
      if(g.profile.stats.bestRarity<tier)g.profile.stats.bestRarity=tier;
      fxText(api,"+"+(coins+bonus)+" 🪙",t.color,chest.x,chest.y-35);
      api.emitParticles(chest.x,chest.y,22,t.color);
      api.sound([390,480,580,745,990][tier],.17);
      toast((tier>=3?"✦ ":"")+"BAÚ "+t.name.toUpperCase()+" • +"+(coins+bonus)+" moedas, +"+dust+" ecos"+(tier>=2?" • "+g.run.relics[g.run.relics.length-1]:""),t.color);
      if(g.run.opened===3&&g.run.region==="torre"&&g.boss&&!g.boss.awake){
        const b=api.get(g.boss.id);if(b){b.opacity=1;g.boss.awake=true;api.cameraShake(11);toast("🔔 O REGENTE DESPERTOU! O décimo terceiro sino chama por você.","#f7a0ca");api.sound(170,.5);}
      }
      if(g.run.opened>=g.chests.length){toast("Todos os lacres desta expedição foram abertos! Guarde o saque ou enfrente o Regente.");}
    }
    function blocked(mob,api,nx,ny){
      const o=api.get(mob.id);if(!o)return true;
      for(const b of api.getAll("barreira")){
        if(!b.visible||!b.solid)continue;
        if(Math.abs(nx-b.x)<(o.w+b.w)/2&&Math.abs(ny-b.y)<(o.h+b.h)/2)return true;
      }
      return false;
    }
    function takeDamage(api,damage){
      if(g.hurtCd>0||g.modal||!g.run)return;
      g.hp-=Math.max(1,damage-g.profile.upgrades.light*1.5);g.hurtCd=.95;
      api.cameraShake(7);api.sound(145,.12);
      if(g.hp<=0){g.hp=0;bank(api,true);return;}
      toast("♥ Cuidado! Você sofreu dano.","#ff98a9");
    }
    function attack(api,player){
      if(g.attackCd>0||!g.run||g.modal)return;
      g.attackCd=.36;
      const dx=g.dir.x,dy=g.dir.y;
      const sx=player.x+dx*43,sy=player.y+dy*43;
      api.emitParticles(sx,sy,11,"#e6feff");api.sound(335,.075);
      const effect=api.spawn("circle",{name:"Corte de Luz",x:sx,y:sy,w:73,h:64,color:"#b9fff3",opacity:.45,layer:21});
      g.fx.push({id:effect.id,life:.15});
      for(const m of g.mobs){
        const o=api.get(m.id);if(!o||m.hp<=0)continue;
        const px=o.x-player.x,py=o.y-player.y,d=Math.hypot(px,py);
        if(d>86||d<.001||px/d*dx+py/d*dy<-.18)continue;
        m.hp-=1+g.profile.upgrades.blade;
        o.x+=dx*15;o.y+=dy*15;api.emitParticles(o.x,o.y,8,"#fbd4b5");
        fxText(api,"-"+(1+g.profile.upgrades.blade),"#f4aaca",o.x,o.y-20);
        if(m.hp<=0){m.hp=0;o.visible=false;g.run.kills++;g.run.coins+=6+zoneIndex()*3;api.emitParticles(o.x,o.y,15,"#ffcba3");api.sound(260,.08);if(g.run.kills%4===0)g.hp=Math.min(maxHp(),g.hp+13);}
      }
      if(g.boss?.awake&&g.boss.hp>0){
        const o=api.get(g.boss.id);
        if(o){
          const px=o.x-player.x,py=o.y-player.y,d=Math.hypot(px,py);
          if(d<116&&(d<.001||px/d*dx+py/d*dy>-.18)){
            g.boss.hp-=1+g.profile.upgrades.blade;api.emitParticles(o.x,o.y,12,"#ffd0bf");api.cameraShake(2);
            fxText(api,"-"+(1+g.profile.upgrades.blade),"#ffb2de",o.x,o.y-65);
            if(g.boss.hp<=0)win(api);
          }
        }
      }
    }
    function hitbox(a,b){
      return !!(a&&b&&a.visible!==false&&b.visible!==false&&Math.abs(a.x-b.x)<(a.w+b.w)/2&&Math.abs(a.y-b.y)<(a.h+b.h)/2);
    }
    function projectile(api,x,y,vx,vy,damage=10,color="#b88eff"){
      const o=api.spawn("circle",{name:"Estilhaço da Bruma",x,y,w:12,h:12,color,layer:17,opacity:.9});
      g.shots.push({id:o.id,vx,vy,ttl:3.5,damage});
    }
    function enemiesTick(api,dt,player){
      const solids=api.getAll("barreira");
      for(const m of g.mobs){
        if(m.hp<=0)continue;
        const o=api.get(m.id);if(!o)continue;
        m.hitCd-=dt;m.shotCd-=dt;
        const dx=player.x-o.x,dy=player.y-o.y,dist=Math.hypot(dx,dy)||1;
        if(dist<480){
          const vx=(dx/dist)*m.speed*dt,vy=(dy/dist)*m.speed*dt;
          if(!blocked(m,api,o.x+vx,o.y))o.x+=vx;
          if(!blocked(m,api,o.x,o.y+vy))o.y+=vy;
          if(m.kind==="clock"&&m.shotCd<=0&&dist<360){
            projectile(api,o.x,o.y,dx/dist*122,dy/dist*122,12,"#ffac9b");m.shotCd=rnd(2.2,3.2);
          }
          if(hitbox(player,o)&&m.hitCd<=0){takeDamage(api,14+zoneIndex()*3);m.hitCd=1.1;}
        }else{
          m.orbit+=dt;const walk=Math.sin(m.orbit)*dt*14;
          if(!blocked(m,api,o.x+walk,o.y))o.x+=walk;
        }
      }
      if(g.boss?.awake&&g.boss.hp>0){
        const b=api.get(g.boss.id);if(b){
          g.boss.shotCd-=dt;const dx=player.x-b.x,dy=player.y-b.y,d=Math.hypot(dx,dy)||1;
          if(d<390){
            const vx=dx/d*40*dt,vy=dy/d*40*dt;
            if(!blocked({id:b.id},api,b.x+vx,b.y+vy))b.x+=vx;
            if(!blocked({id:b.id},api,b.x,b.y+vy))b.y+=vy;
          }
          if(d<75)takeDamage(api,18);
          if(g.boss.shotCd<=0){
            g.boss.shotCd=g.boss.hp<10?1.7:2.4;
            for(let i=0;i<8;i++){
              const a=i*Math.PI/4+g.globalClock*.25;
              projectile(api,b.x,b.y,Math.cos(a)*114,Math.sin(a)*114,g.boss.hp<10?18:13,"#ff9ccc");
            }
            api.sound(118,.19);api.cameraShake(3);
          }
        }
      }
      for(let i=g.shots.length-1;i>=0;i--){
        const p=g.shots[i],o=api.get(p.id);
        if(!o){g.shots.splice(i,1);continue;}
        o.x+=p.vx*dt;o.y+=p.vy*dt;p.ttl-=dt;
        if(hitbox(player,o)){takeDamage(api,p.damage);p.ttl=0;}
        if(p.ttl<=0){api.remove(p.id);g.shots.splice(i,1);}
      }
    }
    function bank(api,died=false){
      if(!g.run)return;
      const r=g.run,ratio=died?.5:1;
      const coins=Math.floor(r.coins*ratio),dust=Math.floor(r.dust*ratio),collected=[];
      for(const n of r.relics){if(!g.profile.relics.includes(n)){g.profile.relics.push(n);collected.push(n);}else{g.profile.coins+=8;}}
      g.profile.coins+=coins;g.profile.dust+=dust;g.profile.totalChests+=r.opened;g.profile.totalKills+=r.kills;
      if(died)g.profile.deaths++;
      g.profile.stats.bestRun=Math.max(g.profile.stats.bestRun,r.opened);
      const clearedTower=r.region==="torre"&&g.profile.wins>0;
      g.pendingReport={chests:r.opened,coins,dust,relics:collected,died};
      g.run=null;save(api);closePanel();api.loadScene(chapterNames[0]);
      if(!died&&r.opened>=5&&r.region==="bosque"&&g.profile.totalChests>=5)toast("A Forja está disponível! Novos mistérios esperam.");
      if(!died&&r.opened>=5&&r.region==="forja"&&g.profile.totalChests>=12)toast("O caminho da Torre foi revelado!");
    }
    function win(api){
      if(!g.run)return;
      g.profile.wins++;
      const unique="Sino que não Soou";
      if(!g.run.relics.includes(unique))g.run.relics.push(unique);
      g.pendingEnding=true;g.run.coins+=180;g.run.dust+=18;
      bank(api,false);
      g.pendingEnding=true;
      toast("🏆 O REGENTE CAIU — AS MEMÓRIAS RETORNAM!","#ffdf9b");
    }
    function nearest(api,player){
      let best=null,dist=82;
      if(g.run){
        for(const c of g.chests){
          if(c.open)continue;
          const d=Math.hypot(player.x-c.x,player.y-c.y);
          if(d<dist){dist=d;best={type:"chest",label:"ABRIR BAÚ",item:c};}
        }
        const returnStone=api.get("Marco de Retorno");
        if(returnStone){const d=Math.hypot(player.x-returnStone.x,player.y-returnStone.y);if(d<dist){dist=d;best={type:"return",label:"RETORNAR AO FAROL"};}}
      }else{
        const candidates=[
          ["Mira, a Arquivista","shop","OFICINA DE MIRA"],
          ["Portal do Bosque","bosque","ENTRAR NO BOSQUE"],
          ["Portal da Forja","forja","ENTRAR NA FORJA"],
          ["Portal da Torre","torre","ENTRAR NA TORRE"],
          ["Biblioteca","book","LER CÓDICE"]
        ];
        for(const [name,type,label] of candidates){
          const o=api.get(name);if(!o)continue;
          const d=Math.hypot(player.x-o.x,player.y-o.y);
          if(d<dist){dist=d;best={type,label};}
        }
      }
      return best;
    }
    function interact(api){
      const n=g.near;
      if(!n){toast("Aproxime-se de um baú, portal ou personagem.");return;}
      if(n.type==="chest"){chestOpen(api,n.item);}
      else if(n.type==="return")bank(api,false);
      else if(n.type==="shop"||n.type==="book")openPanel(n.type);
      else if(regionNames[n.type])travel(api,n.type);
    }
    function travel(api,id){
      const p=g.profile;
      if(!regionNames[id])return;
      if(id==="forja"&&p.totalChests<5){toast("Abra e guarde 5 baús primeiro.");return;}
      if(id==="torre"&&(p.totalChests<12||!p.seen.forja)){toast("Explore a Forja e guarde 12 baús no total.");return;}
      closePanel();g.pendingReport=null;newRun(id);
      api.loadScene(regionNames[id]);
    }
    function queueTick(api){
      if(!g.queue.length)return;
      const item=g.queue.shift(),type=item.name;
      if(type==="close")closePanel();
      else if(type==="menu")openPanel("menu");
      else if(type==="story"||type==="routes"||type==="shop"||type==="book"||type==="inventory"||type==="help")openPanel(type);
      else if(type==="interact"){if(!g.modal)interact(api);}
      else if(type==="return"){if(g.run)bank(api,false);}
      else if(type==="travel")travel(api,item.value);
      else if(type==="buy"){
        if(g.run){toast("Compre melhorias no refúgio.");return;}
        const b=boosts[item.value];if(!b)return;
        const lv=g.profile.upgrades[item.value]||0,cost=b.base*(lv+1);
        if(lv<b.max&&g.profile.coins>=cost){
          g.profile.coins-=cost;g.profile.upgrades[item.value]++;
          g.hp=maxHp();save(api);toast("MELHORIA ADQUIRIDA: "+b.name,"#8bffd7");openPanel("shop");api.sound(750,.11);
        }else toast("Moedas insuficientes ou nível máximo.");
      }
    }
    function tickFx(api,dt){
      for(let i=g.fx.length-1;i>=0;i--){
        const t=g.fx[i],o=api.get(t.id);
        if(o){o.y-=dt*21;o.opacity=clamp(t.life/.9,0,1);}
        t.life-=dt;
        if(t.life<=0){api.remove(t.id);g.fx.splice(i,1);}
      }
    }
    function syncVisual(api,player,dt){
      const figure=api.get("Sombra do Catador");if(figure){figure.x=player.x;figure.y=player.y-2;}
      if(!g.ui)return;
      if(performance.now()>g.msgEnd){q("lb-toast").style.opacity="0";}
      g.lastHud+=dt;
      if(g.lastHud<.08)return;
      g.lastHud=0;
      q("lb-region").textContent="✦ "+g.scene;
      const region=g.run;
      q("lb-info").textContent=region
        ?"♥ "+Math.ceil(g.hp)+"/"+maxHp()+"  ·  📦 "+region.opened+"/"+(8+g.profile.upgrades.bag*2)+"  ·  🪙 "+region.coins+"  ·  ✦ "+region.dust+(g.boss?.awake&&g.boss.hp>0?"  ·  🔔 "+g.boss.hp+" HP":"")
        :"🪙 "+g.profile.coins+"  ·  ✦ "+g.profile.dust+"  ·  💎 "+g.profile.relics.length+" relíquias";
      q("lb-health").style.width=clamp(g.hp/maxHp()*100,0,100)+"%";
      q("lb-health").style.background=g.hp<maxHp()*.3?"#ff8797":"linear-gradient(90deg,#54ecc0,#9af5aa)";
      const nearEl=q("lb-near"),inter=q("lb-interact");
      if(g.near&&!g.modal){
        nearEl.style.display="block";inter.style.display="block";
        nearEl.textContent="✦ "+g.near.label+" • pressione B / F";
        inter.textContent=g.near.label;
      }else{nearEl.style.display="none";inter.style.display="none";}
    }
    function tick(scene,api,dt){
      if(!g.profile){g.profile=Object.assign(fresh(),api.loadData("lacres-profile-1",null)||{});g.profile.seen||={};g.profile.stats||={bestRarity:0,bestRun:0};g.profile.relics||=[];g.profile.upgrades=Object.assign(fresh().upgrades,g.profile.upgrades||{});}
      if(!g.ui)initUI();
      if(g.scene!==api.sceneName)stageEnter(scene,api);
      g.globalClock+=dt;g.attackCd=Math.max(0,g.attackCd-dt);g.hurtCd=Math.max(0,g.hurtCd-dt);
      const player=api.getByTag("catador");
      queueTick(api);
      if(!player)return;
      const moveX=api.input.x+(api.isKeyDown("d")||api.isKeyDown("arrowright")?1:0)-(api.isKeyDown("a")||api.isKeyDown("arrowleft")?1:0);
      const moveY=api.input.y+(api.isKeyDown("s")||api.isKeyDown("arrowdown")?1:0)-(api.isKeyDown("w")||api.isKeyDown("arrowup")?1:0);
      if(Math.hypot(moveX,moveY)>.1){const mag=Math.hypot(moveX,moveY);g.dir.x=moveX/mag;g.dir.y=moveY/mag;}
      player.speed=220+g.profile.upgrades.boots*22;
      g.near=nearest(api,player);
      const b=!!(api.input.action||api.isKeyDown("f"));
      if(b&&!g.prevB&&!g.modal)interact(api);
      g.prevB=b;
      if(g.run&&!g.modal){
        g.run.time+=dt;
        const atk=!!(api.input.jump||api.isKeyDown(" ")||api.isKeyDown("enter"));
        if(atk&&g.attackCd<=0)attack(api,player);
        if(g.run)enemiesTick(api,dt,player);
        tickFx(api,dt);
      }
      syncVisual(api,player,dt);
    }
    g.tick=tick;
    window[key]=g;
  }
  window[key].tick(scene,api,dt);
})(scene,api,dt);

scenes.script:
(function gameCore(scene,api,dt){
  const key="__AURENIX_LACRES_BRUMA_V1__";
  if(!window[key]){
    const chapterNames=["Refúgio do Farol","Bosque dos Sussurros","Forja Silenciosa","Torre do Décimo Terceiro Sino"];
    const regionNames={bosque:chapterNames[1],forja:chapterNames[2],torre:chapterNames[3]};
    const lore=[
      {title:"Prólogo — A Décima Terceira Batida",body:"No mundo de Orval, toda lembrança era guardada em pequenos lacres de metal. Quando o Grande Sino tocou pela décima terceira vez, cidades esqueceram seus nomes, rios perderam os caminhos e as pessoas pararam de reconhecer os próprios rostos. Só o farol de Eira continuou brilhando. Você é o último dos Catadores de Ecos: alguém capaz de abrir os baús onde o passado ficou preso."},
      {title:"I — O Cartógrafo sem Rosto",body:"Na primeira noite da Névoa, o cartógrafo Kael entrou no bosque levando um mapa com uma estrada que não existia. Ele escreveu uma frase na margem: 'A bruma não destrói memórias. Ela as escolhe.' Depois desapareceu. Um dos seus lacres foi encontrado no interior de um baú, ainda quente."},
      {title:"II — As Máquinas que Sonhavam",body:"A Forja Silenciosa construiu relógios para medir o tempo até a próxima batida do Sino. Mas nenhuma máquina concordava com as outras. Os artesãos descobriram que o tempo não estava quebrado: cada pessoa agora vivia numa lembrança diferente. Mira foi a única a perceber que as peças retiradas dos baús tinham sempre o mesmo símbolo: um olho fechado."},
      {title:"III — A Promessa de Eira",body:"Eira não construiu o farol para guiar viajantes, mas para lembrar o nome do filho que havia perdido. Todas as noites, ela o acendia e contava treze batidas em silêncio. O décimo terceiro toque nunca deveria existir. Para impedir que o mundo esquecesse a dor, alguém roubou a última batida e a escondeu numa torre."},
      {title:"IV — O Regente do Silêncio",body:"O Regente era a voz do próprio Sino. Não era um monstro: nasceu do desejo de apagar histórias tristes. Aprendeu a proteger cada memória num baú e, em troca, fez com que ninguém conseguisse se lembrar de quem era. O Regente espera no topo da Torre. Quando o enfrentar, estará lutando contra a tentação de esquecer."},
      {title:"Epílogo — O Mundo Lembra",body:"Ao quebrar o lacre do Sino, você não devolveu apenas os nomes das cidades. Devolveu também saudade, medo e arrependimento. Eira lembrou do filho. Kael voltou a reconhecer o próprio mapa. A bruma permaneceu nas florestas — mas agora guardava histórias, não pessoas. Ainda existem lacres perdidos. Talvez um último baú esteja esperando por você."}
    ];
    const tiers=[
      {name:"Comum",color:"#bcd0dd",weight:56,coins:[9,17],dust:1},
      {name:"Incomum",color:"#6ce2ac",weight:27,coins:[16,28],dust:2},
      {name:"Raro",color:"#74b5ff",weight:12,coins:[27,44],dust:3},
      {name:"Épico",color:"#ca91ff",weight:4,coins:[43,69],dust:5},
      {name:"Lendário",color:"#ffc86c",weight:1,coins:[75,120],dust:9}
    ];
    const relicPool=[
      ["Pedaço de Barbante","Prego de Eira","Lacre Enferrujado","Moeda Sem Face"],
      ["Pena do Vigia","Fio de Luz","Chave Retorcida","Botão de Kael"],
      ["Lâmina de Orvalho","Olho de Âmbar","Mapa Invertido","Brasa da Forja"],
      ["Relógio Sem Ponteiros","Manto de Treze Estrelas","Coração da Lanterna"],
      ["A Última Batida","Nome Verdadeiro de Eira","Núcleo do Silêncio"]
    ];
    const boosts={
      blade:{name:"Lâmina Ecoante",desc:"+1 dano por nível",base:45,max:6,icon:"⚔️"},
      boots:{name:"Botas do Cartógrafo",desc:"+22 de velocidade por nível",base:35,max:6,icon:"👟"},
      light:{name:"Lanterna de Eira",desc:"+20 vida máxima por nível",base:40,max:5,icon:"🏮"},
      luck:{name:"Instinto do Catador",desc:"Mais chance de baús raros",base:65,max:5,icon:"🍀"},
      bag:{name:"Bolsa sem Fundo",desc:"+2 baús por expedição",base:60,max:4,icon:"🎒"}
    };
    const fresh=()=>({coins:0,dust:0,totalChests:0,totalKills:0,deaths:0,wins:0,seen:{},relics:[],upgrades:{blade:0,boots:0,light:0,luck:0,bag:0},chapter:0,stats:{bestRarity:0,bestRun:0},intro:false});
    const x=document;
    const q=id=>x.getElementById(id);
    const g={
      profile:null,started:false,scene:"",run:null,hp:100,attackCd:0,hurtCd:0,dir:{x:1,y:0},
      prevB:false,mobs:[],chests:[],shots:[],fx:[],queue:[],near:null,modal:"",msgEnd:0,lastHud:-1,
      danger:0,globalClock:0,warningCd:0,boss:null,pendingReport:null,pendingEnding:false,
      ui:false,assets:{closed:"lb-chest",open:"lb-open",hero:"lb-hero",moth:"lb-moth",clock:"lb-clock",ghost:"lb-ghost",boss:"lb-boss"}
    };
    const rnd=(lo,hi)=>lo+Math.random()*(hi-lo);
    const pick=a=>a[Math.floor(Math.random()*a.length)];
    const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
    const escape=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
    function save(api){api.saveData("lacres-profile-1",g.profile);}
    function initUI(){
