    const spots=[
      [-425,-257],[-255,-295],[-55,-285],[170,-278],[401,-280],
      [-390,230],[-200,270],[24,285],[265,273],[430,225],
      [-285,-45],[-80,138],[158,-98],[342,42],[-38,-95],[500,-82],
