    const enemySpots=[[-270,-180],[-50,-245],[225,-235],[355,160],[-395,145],[104,80],[-75,185],[430,-75],[225,265],[-210,80]];
    function spawnChests(scene,api,region){
      const shuffled=spots.slice().sort(()=>Math.random()-.5);
      const num=region==="bosque"?8:region==="forja"?9:8;
      for(let i=0;i<num;i++){
