        g.mobs.push({id:mob.id,kind,hp:kind==="clock"?3:2,maxHp:kind==="clock"?3:2,speed:kind==="moth"?67:kind==="clock"?59:54,hitCd:0,shotCd:rnd(1.3,3),orbit:rnd(-3.14,3.14)});
