    function zoneIndex(){return g.scene===chapterNames[1]?0:g.scene===chapterNames[2]?1:2;}
    function coinRoll(tier){const t=tiers[tier],mult=1+zoneIndex()*.34+(g.profile.wins>0?.2:0);return Math.round(rnd(t.coins[0],t.coins[1])*mult);}
    function rarityRoll(){
      const luck=g.profile.upgrades.luck||0,zone=zoneIndex();
      const weights=tiers.map(t=>t.weight);
      const shift=luck*1.9+zone*1.35+(g.profile.wins>0?1.2:0);
      weights[0]=Math.max(16,weights[0]-shift*2.2);weights[1]=Math.max(13,weights[1]-shift*.45);
      weights[2]+=shift*1.55;weights[3]+=shift*.82;weights[4]+=shift*.28;
      const total=weights.reduce((a,b)=>a+b,0);let roll=Math.random()*total;
      for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<=0)return i;}return 4;
    }
    function fxText(api,t,color,x,y){
      const o=api.spawn("text",{name:"Efeito",text:t,fontSize:14,color,x,y,w:260,h:30,layer:30});
      g.fx.push({id:o.id,life:1.2});
    }
    function chestOpen(api,chest){
      if(!g.run||chest.open)return;
      if(g.run.opened>=8+g.profile.upgrades.bag*2){toast("🎒 Bolsa cheia. Guarde suas memórias no refúgio!","#ffce9c");return;}
      const o=api.get(chest.id);if(!o)return;
      chest.open=true;o.assetId=g.assets.open;o.opacity=.75;
      const halo=api.get(chest.halo);if(halo)halo.color="#f0d18b";
      let tier=rarityRoll(); if(g.run.misses>=5&&tier<2)tier=2;g.run.misses=tier>=2?0:(g.run.misses||0)+1;const t=tiers[tier],coins=coinRoll(tier),dust=t.dust+zoneIndex();
      const bonus=(g.run.opened+1)%5===0?7:0;
      g.run.coins+=coins+bonus;g.run.dust+=dust;g.run.opened++;
      if(tier>=2){g.run.rares++;const relic=pick(relicPool[tier]);g.run.relics.push(relic);}
      else if(Math.random()<.10)g.hp=Math.min(maxHp(),g.hp+12);
      if(g.profile.stats.bestRarity<tier)g.profile.stats.bestRarity=tier;
      fxText(api,"+"+(coins+bonus)+" 🪙",t.color,chest.x,chest.y-35);
      api.emitParticles(chest.x,chest.y,22,t.color);
      api.sound([390,480,580,745,990][tier],.17);
      toast((tier>=3?"✦ ":"")+"BAÚ "+t.name.toUpperCase()+" • +"+(coins+bonus)+" moedas, +"+dust+" ecos"+(tier>=2?" • "+g.run.relics[g.run.relics.length-1]:""),t.color);
      if(g.run.opened===3&&g.run.region==="torre"&&g.boss&&!g.boss.awake){
        const b=api.get(g.boss.id);if(b){b.opacity=1;g.boss.awake=true;api.cameraShake(11);toast("🔔 O REGENTE DESPERTOU! O décimo terceiro sino chama por você.","#f7a0ca");api.sound(170,.5);}
      }
      if(g.run.opened>=g.chests.length){toast("Todos os lacres desta expedição foram abertos! Guarde o saque ou enfrente o Regente.");}
    }
    function blocked(mob,api,nx,ny){
      const o=api.get(mob.id);if(!o)return true;
      for(const b of api.getAll("barreira")){
        if(!b.visible||!b.solid)continue;
        if(Math.abs(nx-b.x)<(o.w+b.w)/2&&Math.abs(ny-b.y)<(o.h+b.h)/2)return true;
      }
      return false;
    }
    function takeDamage(api,damage){
      if(g.hurtCd>0||g.modal||!g.run)return;
      g.hp-=Math.max(1,damage-g.profile.upgrades.light*1.5);g.hurtCd=.95;
      api.cameraShake(7);api.sound(145,.12);
      if(g.hp<=0){g.hp=0;bank(api,true);return;}
      toast("♥ Cuidado! Você sofreu dano.","#ff98a9");
    }
    function attack(api,player){
      if(g.attackCd>0||!g.run||g.modal)return;
      g.attackCd=.36;
      const dx=g.dir.x,dy=g.dir.y;
      const sx=player.x+dx*43,sy=player.y+dy*43;
      api.emitParticles(sx,sy,11,"#e6feff");api.sound(335,.075);
      const effect=api.spawn("circle",{name:"Corte de Luz",x:sx,y:sy,w:73,h:64,color:"#b9fff3",opacity:.45,layer:21});
      g.fx.push({id:effect.id,life:.15});
      for(const m of g.mobs){
        const o=api.get(m.id);if(!o||m.hp<=0)continue;
        const px=o.x-player.x,py=o.y-player.y,d=Math.hypot(px,py);
        if(d>86||d<.001||px/d*dx+py/d*dy<-.18)continue;
        m.hp-=1+g.profile.upgrades.blade;
        o.x+=dx*15;o.y+=dy*15;api.emitParticles(o.x,o.y,8,"#fbd4b5");
        fxText(api,"-"+(1+g.profile.upgrades.blade),"#f4aaca",o.x,o.y-20);
        if(m.hp<=0){m.hp=0;o.visible=false;g.run.kills++;g.run.coins+=6+zoneIndex()*3;api.emitParticles(o.x,o.y,15,"#ffcba3");api.sound(260,.08);if(g.run.kills%4===0)g.hp=Math.min(maxHp(),g.hp+13);}
      }
      if(g.boss?.awake&&g.boss.hp>0){
        const o=api.get(g.boss.id);
        if(o){
          const px=o.x-player.x,py=o.y-player.y,d=Math.hypot(px,py);
          if(d<116&&(d<.001||px/d*dx+py/d*dy>-.18)){
            g.boss.hp-=1+g.profile.upgrades.blade;api.emitParticles(o.x,o.y,12,"#ffd0bf");api.cameraShake(2);
            fxText(api,"-"+(1+g.profile.upgrades.blade),"#ffb2de",o.x,o.y-65);
            if(g.boss.hp<=0)win(api);
          }
        }
      }
    }
    function hitbox(a,b){
      return !!(a&&b&&a.visible!==false&&b.visible!==false&&Math.abs(a.x-b.x)<(a.w+b.w)/2&&Math.abs(a.y-b.y)<(a.h+b.h)/2);
    }
    function projectile(api,x,y,vx,vy,damage=10,color="#b88eff"){
      const o=api.spawn("circle",{name:"Estilhaço da Bruma",x,y,w:12,h:12,color,layer:17,opacity:.9});
      g.shots.push({id:o.id,vx,vy,ttl:3.5,damage});
    }
    function enemiesTick(api,dt,player){
      const solids=api.getAll("barreira");
      for(const m of g.mobs){
        if(m.hp<=0)continue;
        const o=api.get(m.id);if(!o)continue;
        m.hitCd-=dt;m.shotCd-=dt;
        const dx=player.x-o.x,dy=player.y-o.y,dist=Math.hypot(dx,dy)||1;
        if(dist<480){
          const vx=(dx/dist)*m.speed*dt,vy=(dy/dist)*m.speed*dt;
          if(!blocked(m,api,o.x+vx,o.y))o.x+=vx;
          if(!blocked(m,api,o.x,o.y+vy))o.y+=vy;
          if(m.kind==="clock"&&m.shotCd<=0&&dist<360){
            projectile(api,o.x,o.y,dx/dist*122,dy/dist*122,12,"#ffac9b");m.shotCd=rnd(2.2,3.2);
          }
          if(hitbox(player,o)&&m.hitCd<=0){takeDamage(api,14+zoneIndex()*3);m.hitCd=1.1;}
        }else{
          m.orbit+=dt;const walk=Math.sin(m.orbit)*dt*14;
          if(!blocked(m,api,o.x+walk,o.y))o.x+=walk;
        }
      }
      if(g.boss?.awake&&g.boss.hp>0){
        const b=api.get(g.boss.id);if(b){
          g.boss.shotCd-=dt;const dx=player.x-b.x,dy=player.y-b.y,d=Math.hypot(dx,dy)||1;
          if(d<390){
            const vx=dx/d*40*dt,vy=dy/d*40*dt;
            if(!blocked({id:b.id},api,b.x+vx,b.y+vy))b.x+=vx;
            if(!blocked({id:b.id},api,b.x,b.y+vy))b.y+=vy;
          }
          if(d<75)takeDamage(api,18);
          if(g.boss.shotCd<=0){
            g.boss.shotCd=g.boss.hp<10?1.7:2.4;
            for(let i=0;i<8;i++){
              const a=i*Math.PI/4+g.globalClock*.25;
              projectile(api,b.x,b.y,Math.cos(a)*114,Math.sin(a)*114,g.boss.hp<10?18:13,"#ff9ccc");
            }
            api.sound(118,.19);api.cameraShake(3);
          }
        }
      }
      for(let i=g.shots.length-1;i>=0;i--){
        const p=g.shots[i],o=api.get(p.id);
        if(!o){g.shots.splice(i,1);continue;}
        o.x+=p.vx*dt;o.y+=p.vy*dt;p.ttl-=dt;
        if(hitbox(player,o)){takeDamage(api,p.damage);p.ttl=0;}
        if(p.ttl<=0){api.remove(p.id);g.shots.splice(i,1);}
      }
    }
    function bank(api,died=false){
      if(!g.run)return;
      const r=g.run,ratio=died?.5:1;
      const coins=Math.floor(r.coins*ratio),dust=Math.floor(r.dust*ratio),collected=[];
      for(const n of r.relics){if(!g.profile.relics.includes(n)){g.profile.relics.push(n);collected.push(n);}else{g.profile.coins+=8;}}
      g.profile.coins+=coins;g.profile.dust+=dust;g.profile.totalChests+=r.opened;g.profile.totalKills+=r.kills;
      if(died)g.profile.deaths++;
      g.profile.stats.bestRun=Math.max(g.profile.stats.bestRun,r.opened);
      const clearedTower=r.region==="torre"&&g.profile.wins>0;
      g.pendingReport={chests:r.opened,coins,dust,relics:collected,died};
      g.run=null;save(api);closePanel();api.loadScene(chapterNames[0]);
      if(!died&&r.opened>=5&&r.region==="bosque"&&g.profile.totalChests>=5)toast("A Forja está disponível! Novos mistérios esperam.");
