    function nearest(api,player){
      let best=null,dist=82;
      if(g.run){
        for(const c of g.chests){
          if(c.open)continue;
          const d=Math.hypot(player.x-c.x,player.y-c.y);
          if(d<dist){dist=d;best={type:"chest",label:"ABRIR BAÚ",item:c};}
        }
        const returnStone=api.get("Marco de Retorno");
        if(returnStone){const d=Math.hypot(player.x-returnStone.x,player.y-returnStone.y);if(d<dist){dist=d;best={type:"return",label:"RETORNAR AO FAROL"};}}
      }else{
        const candidates=[
          ["Mira, a Arquivista","shop","OFICINA DE MIRA"],
          ["Portal do Bosque","bosque","ENTRAR NO BOSQUE"],
          ["Portal da Forja","forja","ENTRAR NA FORJA"],
          ["Portal da Torre","torre","ENTRAR NA TORRE"],
          ["Biblioteca","book","LER CÓDICE"]
        ];
        for(const [name,type,label] of candidates){
          const o=api.get(name);if(!o)continue;
          const d=Math.hypot(player.x-o.x,player.y-o.y);
          if(d<dist){dist=d;best={type,label};}
        }
      }
      return best;
    }
