    function blocked(mob,api,nx,ny){
      const o=api.get(mob.id);if(!o)return true;
      for(const b of api.getAll("barreira")){
        if(!b.visible||!b.solid)continue;
        if(Math.abs(nx-b.x)<(o.w+b.w)/2&&Math.abs(ny-b.y)<(o.h+b.h)/2)return true;
      }
      return false;
    }
    function takeDamage(api,damage){
