        o.x+=dx*15;o.y+=dy*15;api.emitParticles(o.x,o.y,8,"#fbd4b5");
        fxText(api,"-"+(1+g.profile.upgrades.blade),"#f4aaca",o.x,o.y-20);
        if(m.hp<=0){m.hp=0;o.visible=false;g.run.kills++;g.run.coins+=6+zoneIndex()*3;api.emitParticles(o.x,o.y,15,"#ffcba3");api.sound(260,.08);if(g.run.kills%4===0)g.hp=Math.min(maxHp(),g.hp+13);}
      }
      if(g.boss?.awake&&g.boss.hp>0){
        const o=api.get(g.boss.id);
        if(o){
          const px=o.x-player.x,py=o.y-player.y,d=Math.hypot(px,py);
          if(d<116&&(d<.001||px/d*dx+py/d*dy>-.18)){
