      else if(type==="story"||type==="routes"||type==="shop"||type==="book"||type==="inventory"||type==="help")openPanel(type);
      else if(type==="interact"){if(!g.modal)interact(api);}
      else if(type==="return"){if(g.run)bank(api,false);}
