    function tick(scene,api,dt){
      if(!g.profile){g.profile=Object.assign(fresh(),api.loadData("lacres-profile-1",null)||{});g.profile.seen||={};g.profile.stats||={bestRarity:0,bestRun:0};g.profile.relics||=[];g.profile.upgrades=Object.assign(fresh().upgrades,g.profile.upgrades||{});}
